'use strict';window.garageEmbeddedModels={};function garageDecodeModel(encoded){const bytes=new Uint8Array(encoded.length/4*3);let offset=0;for(let i=0;i<encoded.length;i+=32768){const chunk=atob(encoded.slice(i,i+32768));for(let j=0;j<chunk.length;j++)bytes[offset++]=chunk.charCodeAt(j);}
return new Response(new Blob([bytes.subarray(0,offset)]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();}
window.garageEmbeddedModels.car=(()=>{let encoded='';return()=>{if(!encoded)throw Error('Embedded model already consumed');const pending=garageDecodeModel(encoded);encoded=null;return pending;};})();window.garageEmbeddedModels.tyre=(()=>{let encoded='';return()=>{if(!encoded)throw Error('Embedded model already consumed');const pending=garageDecodeModel(encoded);encoded=null;return pending;};})();
